import {DATA,DEFAULTS,localParts,epoch,time,dateLabel,daily,upcoming,conflicts,ready} from './schedule.js';
const $=id=>document.getElementById(id);
const storage={get(k){try{return localStorage.getItem(k);}catch{return null;}},set(k,v){try{localStorage.setItem(k,v);}catch{}}};
let settings={...DEFAULTS};try{const saved=JSON.parse(storage.get('ridge-settings')||'null');if(saved){for(const k of ['outbound','wait','inbound','villasWait'])if(Number.isFinite(saved[k])&&saved[k]>=0&&saved[k]<=180)settings[k]=saved[k];if(['skip','include'].includes(saved.breakMode))settings.breakMode=saved.breakMode;settings.singleBus=saved.singleBus===true;}}catch{}
let direction=storage.get('ridge-direction')==='home'?'home':'campus';let selectedRoute='campus';let plan=null;
function when(t,now){const d=localParts(new Date(t.at));return d.date===localParts(new Date(now)).date?'Today':dateLabel(d.date);}
function rows(trips,now){return trips.map((t,i)=>{const p=localParts(new Date(t.at));const mins=Math.max(0,Math.ceil((t.at-now)/60000));return `<div class="trip-row"><div><strong>${time(p.minute)}</strong><small>${when(t,now)}${t.estimated?' · Estimated':''}${t.uncertain?' · Red time: unconfirmed':''}${t.arrival?` · Est. arrival ${time(localParts(new Date(t.arrival)).minute)}${localParts(new Date(t.arrival)).date!==p.date?' next day':''}`:''}</small></div><span class="badge">${mins===0?'Scheduled now':mins<60?`${mins} min`:i===0?'Next bus':'Later'}</span></div>`;}).join('');}
function setDirection(value){direction=value;storage.set('ridge-direction',value);render();if(plan)renderPlan();}
function render(){const now=Date.now(),p=localParts();$('today').textContent=dateLabel(p.date);$('campusDirection').setAttribute('aria-pressed',direction==='campus');$('homeDirection').setAttribute('aria-pressed',direction==='home');$('nextLabel').textContent=direction==='campus'?'NEXT AT THE VILLAS':'NEXT FROM COLLEGE · ESTIMATE';$('fromStop').textContent=direction==='campus'?'Villas at Chestnut Ridge':'College · stop to confirm';$('toStop').textContent=direction==='campus'?'College · stop to confirm':'Villas at Chestnut Ridge';const trips=upcoming(now,direction,settings);const next=trips[0];
if(direction==='home'&&!ready(settings)){$('hero').innerHTML='<h2 class="hero-empty">Let’s work out<br>your ride home.</h2><p class="empty">Add the ride to college and its waiting time to calculate return departures.</p><button class="text-button" id="heroSetup">Set travel times →</button>';$('heroSetup').onclick=openSettings;$('upcoming').innerHTML='<p class="empty">Your photos don’t include a weekday college departure timetable. Return estimates will appear here after setup.</p>';}
else if(next){const np=localParts(new Date(next.at)),mins=Math.max(0,Math.ceil((next.at-now)/60000));let title=mins===0?'Scheduled now':mins<60?`${mins} <small>min away</small>`:mins<1440?`${Math.floor(mins/60)}<small>h</small> ${mins%60}<small>m away</small>`:`${Math.floor(mins/1440)} <small>days away</small>`;const ended=np.date!==p.date;$('hero').innerHTML=`<div class="countdown"${mins===0?' style="font-size:40px;letter-spacing:-1px"':''}>${title}</div><p class="departure">${ended?'Next service · ':''}${time(np.minute)}${ended?' · '+dateLabel(np.date):' today'}${direction==='home'?' · estimated':''}</p>${ended?'<p class="small">No more scheduled trips today.</p>':''}`;$('upcoming').innerHTML=rows(trips,now);}
else{$('hero').innerHTML='<h2 class="hero-empty">No scheduled trips</h2>';$('upcoming').innerHTML='<p class="empty">Check the schedule or your settings.</p>';}
const c=conflicts(settings);$('assumptions').textContent=(settings.breakMode==='skip'?'Weekday red times are provisionally skipped. Break lengths are unknown.':'Weekday red times are included but unconfirmed. ')+(direction==='campus'?' Villas entries are used as boarding times.':' Return times use your travel-time estimates.')+(c.length?` ${c.length} turnaround conflicts with one bus — review your travel times.`:'');
const printed=DATA.villas.map(m=>({base:m,minute:m+settings.villasWait+(direction==='home'&&ready(settings)?settings.outbound+settings.wait:0)}));$('fullSchedule').innerHTML=direction==='home'&&!ready(settings)?'<p class="empty" style="grid-column:1/-1">Set travel times to see the estimated return timetable.</p>':printed.map(t=>{const br=DATA.breaks.includes(t.base);return `<span class="time-cell${br?' break':next&&next.base===t.base&&next.serviceDate===p.date?' highlight':''}" title="${br?'Red break marker; '+(settings.breakMode==='skip'?'trip provisionally skipped':'boarding uncertain'):direction==='home'?'Estimated college departure':'Printed Villas boarding time'}">${br?'Ⅱ ':''}${time(t.minute)}${t.minute>=1440?' +1d':''}</span>`;}).join('');
$('connection').textContent=navigator.onLine?'Timetable · not live tracking':'Offline · using the saved timetable';}
function openSettings(){for(const k of ['outbound','wait','inbound','villasWait'])$('settingsForm').elements[k].value=settings[k]??'';$('settingsForm').elements.breakMode.value=settings.breakMode;$('settingsForm').elements.singleBus.checked=settings.singleBus;$('settingsError').textContent='';$('settings').showModal();}
function renderPlan(){if(!plan)return;if(direction==='home'&&!ready(settings)){$('planResults').innerHTML='<p class="empty">Add travel times in Settings to plan your ride home.</p>';return;}const at=epoch(plan.date,plan.minute);const trips=upcoming(at,direction,settings,3,true);$('planResults').innerHTML=(trips[0]&&localParts(new Date(trips[0].at)).date!==plan.date?'<p class="small muted">No trips after your selected time that day. Next available service:</p>':'')+rows(trips,at)+'<p class="small muted">Uses the weekly pattern; holidays and service changes are unconfirmed. '+(settings.breakMode==='skip'?'Red break trips are excluded.':'Red times remain unconfirmed.')+'</p>';}
$('settingsButton').onclick=openSettings;$('adjustButton').onclick=openSettings;$('closeSettings').onclick=()=>$('settings').close();$('settings').addEventListener('click',e=>{if(e.target===$('settings')){const r=$('settings').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('settings').close();}});
$('settingsForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;const next={...settings};for(const k of ['outbound','wait','inbound','villasWait']){const v=f.elements[k].value;next[k]=v===''?(k==='villasWait'?0:null):Number(v);if(next[k]!==null&&(!Number.isInteger(next[k])||next[k]<(k==='outbound'||k==='inbound'?1:0)||next[k]>180)){$('settingsError').textContent='Enter whole minutes between the displayed limits.';return;}}next.breakMode=f.elements.breakMode.value;next.singleBus=f.elements.singleBus.checked;settings=next;storage.set('ridge-settings',JSON.stringify(settings));$('settings').close();render();renderPlan();};
$('resetSettings').onclick=()=>{settings={...DEFAULTS};storage.set('ridge-settings',JSON.stringify(settings));$('settings').close();render();renderPlan();};$('campusDirection').onclick=()=>setDirection('campus');$('homeDirection').onclick=()=>setDirection('home');
function setRoute(r){selectedRoute=r;$('campus').hidden=r!=='campus';$('market').hidden=r!=='market';$('weekdayTab').setAttribute('aria-pressed',r==='campus');$('marketTab').setAttribute('aria-pressed',r==='market');}
$('weekdayTab').onclick=()=>setRoute('campus');$('marketTab').onclick=()=>setRoute('market');
$('marketStops').innerHTML=DATA.market.stops.map((s,i)=>`<span>${i+1}. ${s}</span>`).join('');$('marketTable').innerHTML=DATA.market.rows.map((row,i)=>`<section class="market-round"><h3>${i===3?'Final printed round · boarding unconfirmed':`Round ${i+1}`}</h3><div class="market-grid">${row.map((m,j)=>`<div${i===2&&j<2?' class="red"':''}><small>${DATA.market.stops[j]}</small><strong>${m===null?'—':time(m)}</strong>${i===2&&j<2?'<em>Final departure</em>':''}</div>`).join('')}</div></section>`).join('');
const p=localParts();$('planDate').value=p.date;$('planTime').value=`${String(Math.floor(p.minute/60)).padStart(2,'0')}:${String(p.minute%60).padStart(2,'0')}`;$('plannerForm').onsubmit=e=>{e.preventDefault();const [h,m]=$('planTime').value.split(':').map(Number);plan={date:$('planDate').value,minute:h*60+m};renderPlan();};
render();setInterval(render,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});window.addEventListener('pageshow',render);window.addEventListener('online',render);window.addEventListener('offline',render);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
const mc=document.modelContext;if(mc?.registerTool){try{Promise.resolve(mc.registerTool({name:'plan_shuttle_trip',title:'Plan a shuttle trip',description:'Set direction, date and ready-at time, and display the next three weekday departures. College return trips require configured travel times.',inputSchema:{type:'object',properties:{direction:{type:'string',enum:['campus','home']},date:{type:'string',description:'YYYY-MM-DD in America/New_York'},time:{type:'string',description:'HH:MM, 24-hour Eastern time'}},required:['direction','date','time'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['campus','home'].includes(input.direction)||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(input.time)||Number.isNaN(Date.parse(input.date+'T12:00:00Z'))||new Date(input.date+'T12:00:00Z').toISOString().slice(0,10)!==input.date)throw new Error('Provide a valid direction, date, and time.');const [h,m]=input.time.split(':').map(Number);setRoute('campus');setDirection(input.direction);$('planDate').value=input.date;$('planTime').value=input.time;plan={date:input.date,minute:h*60+m};renderPlan();return {requiresTravelTimes:input.direction==='home'&&!ready(settings),departures:upcoming(epoch(plan.date,plan.minute),direction,settings,3,true).map(t=>({departure:new Date(t.at).toISOString(),estimated:t.estimated})),timezone:DATA.timezone};}})).catch(()=>{});}catch{}}
